"""Generate Healthy Retention PBIR report pages, theme and bookmarks.

Usage: python gen_report.py <path to HealthyRetention.Report>
Writes only inside the report folder. Never touches the semantic model.
"""
import json
import sys
from pathlib import Path

REPORT = Path(sys.argv[1])
DEF = REPORT / "definition"
PAGES = DEF / "pages"
SCHEMA = "https://developer.microsoft.com/json-schemas/fabric/item/report/definition"

# ---------- palette ----------
BG, NAV, CARD, BORDER = "#1C1C22", "#18181D", "#25252D", "#34343E"
TXT, TXT2 = "#F4F2EC", "#A8A6B0"
GOLD, BLUE = "#F2C66D", "#7FA7D9"
SOURCE = "Source: Ghaharian et al. (2023), Mendeley Data, CC BY 4.0"

written = []


def write(path: Path, obj):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    written.append(path)


# ---------- expression helpers ----------
def lit(v):
    if isinstance(v, bool):
        s = "true" if v else "false"
    elif isinstance(v, int):
        s = f"{v}L"
    elif isinstance(v, float):
        s = f"{v}D"
    else:
        s = "'" + str(v).replace("'", "''") + "'"
    return {"expr": {"Literal": {"Value": s}}}


def num(v):  # formatting numbers are doubles
    return {"expr": {"Literal": {"Value": f"{v}D"}}}


def color(c):
    return {"solid": {"color": lit(c)}}


def col(table, name):
    return {"Column": {"Expression": {"SourceRef": {"Entity": table}}, "Property": name}}


def meas(name, table="_Measures"):
    return {"Measure": {"Expression": {"SourceRef": {"Entity": table}}, "Property": name}}


def proj(field, display=None):
    inner = field.get("Column") or field.get("Measure")
    ent = inner["Expression"]["SourceRef"]["Entity"]
    p = {"field": field, "queryRef": f"{ent}.{inner['Property']}", "nativeQueryRef": inner["Property"]}
    if display:
        p["displayName"] = display
    return p


def qref(field):
    inner = field.get("Column") or field.get("Measure")
    return f"{inner['Expression']['SourceRef']['Entity']}.{inner['Property']}"


def src_col(alias, name):
    return {"Column": {"Expression": {"SourceRef": {"Source": alias}}, "Property": name}}


def in_values(values):
    out = []
    for v in values:
        if isinstance(v, str) and v.startswith("datetime'"):
            out.append([{"Literal": {"Value": v}}])
        else:
            out.append([{"Literal": {"Value": "'" + v.replace("'", "''") + "'"}}])
    return out


_fid = [0]


def fname(prefix):
    _fid[0] += 1
    return f"{prefix}_f{_fid[0]:02d}"


def f_in(table, column, values, prefix, exclude=False):
    cond = {"In": {"Expressions": [src_col("d", column)], "Values": in_values(values)}}
    if exclude:
        cond = {"Not": {"Expression": cond}}
    f = {
        "name": fname(prefix),
        "field": col(table, column),
        "type": "Categorical",
        "filter": {"Version": 2, "From": [{"Name": "d", "Entity": table, "Type": 0}],
                   "Where": [{"Condition": cond}]},
        "howCreated": "User",
    }
    if exclude:
        f["objects"] = {"general": [{"properties": {"isInvertedSelectionMode": lit(True)}}]}
    return f


def f_not_blank(table, column, prefix):
    return {
        "name": fname(prefix),
        "field": col(table, column),
        "type": "Advanced",
        "filter": {"Version": 2, "From": [{"Name": "d", "Entity": table, "Type": 0}],
                   "Where": [{"Condition": {"Not": {"Expression": {"Comparison": {
                       "ComparisonKind": 0, "Left": src_col("d", column),
                       "Right": {"Literal": {"Value": "null"}}}}}}}]},
        "howCreated": "User",
    }


def f_between_int(table, column, lo, hi, prefix):
    left = {"Comparison": {"ComparisonKind": 2, "Left": src_col("d", column), "Right": {"Literal": {"Value": f"{lo}L"}}}}
    right = {"Comparison": {"ComparisonKind": 4, "Left": src_col("d", column), "Right": {"Literal": {"Value": f"{hi}L"}}}}
    return {
        "name": fname(prefix),
        "field": col(table, column),
        "type": "Advanced",
        "filter": {"Version": 2, "From": [{"Name": "d", "Entity": table, "Type": 0}],
                   "Where": [{"Condition": {"And": {"Left": left, "Right": right}}}]},
        "howCreated": "User",
    }


def months(start, end):
    (y, m), out = start, []
    while (y, m) <= end:
        out.append(f"datetime'{y}-{m:02d}-01T00:00:00'")
        y, m = (y + 1, 1) if m == 12 else (y, m + 1)
    return out


def page_filters(prefix, cohort=None, new=True, extra=()):
    fs = [f_in("dim_player", "brand", ["casino"], prefix)]
    if new:
        fs.append(f_in("dim_player", "player_type", ["new"], prefix))
    if cohort:
        fs.append(f_in("dim_player", "cohort_month", months(*cohort), prefix))
    fs.extend(extra)
    for i, f in enumerate(fs):
        f["ordinal"] = i
    return {"filters": fs, "filterSortOrder": "Custom"}


# ---------- visual helpers ----------
class Page:
    def __init__(self, name, display, width=1280, height=720):
        self.name, self.display, self.w, self.h = name, display, width, height
        self.visuals, self.z = [], 0

    def add(self, vname, x, y, w, h, visual, filters=None, hidden=False):
        self.z += 1
        vc = {
            "$schema": f"{SCHEMA}/visualContainer/2.2.0/schema.json",
            "name": vname,
            "position": {"x": x, "y": y, "z": self.z * 1000, "height": h, "width": w, "tabOrder": self.z * 1000},
            "visual": visual,
        }
        if filters:
            vc["filterConfig"] = {"filters": filters}
        if hidden:
            vc["isHidden"] = True
        self.visuals.append(vc)
        return vname


def vco(title=None, title_expr=None, show_title=True, bg=True, border=True, border_color=None,
        title_size=None, title_color=None, title_align=None, tooltip_page=None, link=None):
    o = {}
    if title_expr is not None or title is not None:
        tp = {"show": lit(True), "text": {"expr": title_expr} if title_expr else lit(title)}
        if title_size:
            tp["fontSize"] = num(title_size)
        if title_color:
            tp["fontColor"] = color(title_color)
        if title_align:
            tp["alignment"] = lit(title_align)
        o["title"] = [{"properties": tp}]
    elif not show_title:
        o["title"] = [{"properties": {"show": lit(False)}}]
    if not bg:
        o["background"] = [{"properties": {"show": lit(False)}}]
    if not border:
        o["border"] = [{"properties": {"show": lit(False)}}]
    elif border_color:
        o["border"] = [{"properties": {"show": lit(True), "color": color(border_color),
                                       "radius": num(10), "width": num(2)}}]
    if tooltip_page:
        o["visualTooltip"] = [{"properties": {"show": lit(True), "type": lit("Canvas"),
                                              "section": lit(tooltip_page)}}]
    if link:
        o["visualLink"] = [{"properties": link}]
    return o


def textbox(paragraphs, **kw):
    return {
        "visualType": "textbox",
        "objects": {"general": [{"properties": {"paragraphs": paragraphs}}]},
        "visualContainerObjects": vco(show_title=False, **kw),
        "drillFilterOtherVisuals": True,
    }


def run(text, size=11, c=TXT, bold=False, font="Segoe UI"):
    style = {"fontFamily": "Segoe UI Semibold" if bold else font, "fontSize": f"{size}pt", "color": c}
    return {"value": text, "textStyle": style}


def para(*runs, align="left"):
    return {"textRuns": list(runs), "horizontalTextAlignment": align}


def chart(vtype, roles, sort=None, objects=None, field_params=None, **kw):
    qs = {role: {"projections": ps} for role, ps in roles.items()}
    if field_params:
        for role, fp in field_params.items():
            qs[role]["fieldParameters"] = fp
    q = {"queryState": qs}
    if sort:
        q["sortDefinition"] = {"sort": sort, "isDefaultSort": False}
    v = {"visualType": vtype, "query": q, "drillFilterOtherVisuals": True}
    if objects:
        v["objects"] = objects
    v["visualContainerObjects"] = vco(**kw)
    return v


def card(measure, label):
    return chart("card", {"Values": [proj(meas(measure))]},
                 objects={"categoryLabels": [{"properties": {"show": lit(False)}}]},
                 title=label, title_color=TXT2, title_size=10)


def point_colors(category_field, gold_values, metadata=None):
    """Blue default for the series, gold for the categories to watch."""
    out = [{"properties": {"fill": color(BLUE)}}]
    for v in gold_values:
        sel = {"data": [{"scopeId": {"Comparison": {"ComparisonKind": 0, "Left": category_field,
                                                    "Right": {"Literal": {"Value": "'" + v + "'"}}}}}]}
        if metadata:
            sel["metadata"] = metadata
        out.append({"properties": {"fill": color(GOLD)}, "selector": sel})
    return out


def labels_on(extra=None):
    p = {"show": lit(True), "color": color(TXT), "fontSize": num(10)}
    if extra:
        p.update(extra)
    return [{"properties": p}]


def axes(cat_title=False, val_show=True):
    return {
        "categoryAxis": [{"properties": {"showAxisTitle": lit(cat_title), "labelColor": color(TXT2)}}],
        "valueAxis": [{"properties": {"show": lit(val_show), "showAxisTitle": lit(False),
                                      "labelColor": color(TXT2), "gridlineShow": lit(False)}}],
    }


def button(text, fill, text_color, link=None):
    objs = {
        "icon": [{"properties": {"show": lit(False)}, "selector": {"id": "default"}}],
        "text": [{"properties": {"show": lit(True), "text": lit(text), "fontColor": color(text_color),
                                 "fontSize": num(10), "fontFamily": lit("Segoe UI Semibold")},
                  "selector": {"id": "default"}}],
        "fill": [{"properties": {"show": lit(True), "fillColor": color(fill), "transparency": num(0)},
                  "selector": {"id": "default"}}],
        "outline": [{"properties": {"show": lit(True), "lineColor": color(GOLD if fill == GOLD else BORDER),
                                    "roundEdge": num(10)}, "selector": {"id": "default"}}],
    }
    return {"visualType": "actionButton", "objects": objs,
            "visualContainerObjects": vco(show_title=False, bg=False, border=False, link=link),
            "drillFilterOtherVisuals": True}


# ---------- frame ----------
def frame(pg: Page, question, subtitle_measure=None):
    # navigation panel
    pg.add("nav_panel", 0, 0, 200, 720, {
        "visualType": "shape",
        "objects": {
            "shape": [{"properties": {"tileShape": lit("rectangle")}}],
            "fill": [{"properties": {"show": lit(True), "fillColor": color(NAV), "transparency": num(0)},
                      "selector": {"id": "default"}}],
            "outline": [{"properties": {"show": lit(False)}}],
        },
        "visualContainerObjects": vco(show_title=False, bg=False, border=False),
        "drillFilterOtherVisuals": True,
    })
    pg.add("nav_brand", 16, 20, 176, 56, textbox([
        para(run("Healthy Retention", 14, TXT, bold=True)),
        para(run("Casino player journeys, 2019–2020", 9, TXT2)),
    ], bg=False, border=False))
    pg.add("nav_pages", 12, 96, 176, 240, {
        "visualType": "pageNavigator",
        "objects": {
            "layout": [{"properties": {"orientation": {"expr": {"Literal": {"Value": "1D"}}}}}],
            "fill": [
                {"properties": {"show": lit(True), "fillColor": color(NAV), "transparency": num(0)},
                 "selector": {"id": "default"}},
                {"properties": {"show": lit(True), "fillColor": color(CARD), "transparency": num(0)},
                 "selector": {"id": "hover"}},
                {"properties": {"show": lit(True), "fillColor": color(GOLD), "transparency": num(0)},
                 "selector": {"id": "selected"}},
            ],
            "text": [
                {"properties": {"fontColor": color(TXT2), "fontSize": num(11), "fontFamily": lit("Segoe UI"),
                                "horizontalAlignment": lit("left")}, "selector": {"id": "default"}},
                {"properties": {"fontColor": color(BG), "fontFamily": lit("Segoe UI Semibold")},
                 "selector": {"id": "selected"}},
            ],
            "outline": [{"properties": {"show": lit(False)}, "selector": {"id": "default"}}],
        },
        "visualContainerObjects": vco(show_title=False, bg=False, border=False),
        "drillFilterOtherVisuals": True,
    })
    # title + dynamic subtitle
    pg.add("title", 216, 8, 1048, 44, textbox([para(run(question, 24, TXT, bold=True))], bg=False, border=False))
    if subtitle_measure:
        pg.add("subtitle", 216, 50, 1048, 32, {
            "visualType": "shape",
            "objects": {
                "shape": [{"properties": {"tileShape": lit("rectangle")}}],
                "fill": [{"properties": {"show": lit(False)}, "selector": {"id": "default"}}],
                "outline": [{"properties": {"show": lit(False)}}],
            },
            "visualContainerObjects": vco(title_expr=meas(subtitle_measure), title_size=11,
                                          title_color=TXT2, title_align="left", bg=False, border=False),
            "drillFilterOtherVisuals": True,
        })
    pg.add("footer", 216, 694, 1048, 22, textbox([para(run(SOURCE, 8, TXT2))], bg=False, border=False))


KPI_X = [224, 486, 748, 1010]


def kpis(pg: Page, items):
    for i, (vname, measure, label, filters) in enumerate(items):
        pg.add(vname, KPI_X[i], 88, 246, 88, card(measure, label), filters=filters)


def insight(pg: Page, vname, x, y, w, h, heading, lines):
    paras = [para(run(heading, 10, GOLD, bold=True))]
    paras += [para(run(line, 11, TXT)) for line in lines]
    pg.add(vname, x, y, w, h, textbox(paras, border_color=GOLD))


def save_page(pg: Page, filter_config=None, extra=None):
    p = {
        "$schema": f"{SCHEMA}/page/2.0.0/schema.json",
        "name": pg.name,
        "displayName": pg.display,
        "displayOption": "FitToPage",
        "height": pg.h,
        "width": pg.w,
    }
    if filter_config:
        p["filterConfig"] = filter_config
    if extra:
        p.update(extra)
    write(PAGES / pg.name / "page.json", p)
    for vc in pg.visuals:
        write(PAGES / pg.name / "visuals" / vc["name"] / "visual.json", vc)


