def group_chart(measure, title, vtype="clusteredColumnChart"):
    return chart(
        vtype,
        {"Category": [proj(GROUP)], "Y": [proj(meas(measure))]},
        sort=[{"field": GROUP, "direction": "Ascending"}],
        objects={**axes(val_show=False), "dataPoint": point_colors(GROUP, ["Early high-intensity"]),
                 "labels": labels_on()},
        title=title,
    )


