# ---------------- Bookmarks ----------------
BM_SCHEMA = f"{SCHEMA}/bookmark/1.2.0/schema.json"
vtypes = {"btn_pct_new_on": "actionButton", "btn_pct_new_off": "actionButton",
          "btn_pct_prev_on": "actionButton", "btn_pct_prev_off": "actionButton",
          "journey_pct_new": "clusteredBarChart", "journey_pct_prev": "clusteredBarChart"}


def bookmark(name, display, visible):
    vcs = {}
    for v in journey_visuals:
        sv = {"visualType": vtypes[v], "objects": {}}
        if v not in visible:
            sv["display"] = {"mode": "hidden"}
        vcs[v] = {"singleVisual": sv}
    write(DEF / "bookmarks" / f"{name}.bookmark.json", {
        "$schema": BM_SCHEMA,
        "displayName": display,
        "name": name,
        "options": {"targetVisualNames": journey_visuals, "applyOnlyToTargetVisuals": True, "suppressData": True},
        "explorationState": {"version": "1.3", "activeSection": P1,
                             "sections": {P1: {"visualContainers": vcs}}},
    })


bookmark(BM_NEW, "% of new players", {"btn_pct_new_on", "btn_pct_prev_off", "journey_pct_new"})
bookmark(BM_PREV, "% of previous step", {"btn_pct_new_off", "btn_pct_prev_on", "journey_pct_prev"})
write(DEF / "bookmarks" / "bookmarks.json", {
    "$schema": f"{SCHEMA}/bookmarksMetadata/1.0.0/schema.json",
    "items": [{"name": "grp_journey_toggle", "displayName": "Deposit journey toggle",
               "children": [BM_NEW, BM_PREV]}],
})

